<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { getContainerComparison, getContainerDetail, getOverview, getTrend, gradeLabel, recordSourceUrl, type ContainerComparisonItem, type ContainerDetail, type OverviewData, type TrendPoint } from '../api/client'
import GradeSummary from '../components/GradeSummary.vue'
import ComparisonPanel from '../components/ComparisonPanel.vue'
import GradePieChart from '../components/GradePieChart.vue'
import TrendChart from '../components/TrendChart.vue'
import { formatAnomalyValue, formatCurrency, formatNumber, formatPercent, formatPrice } from '../utils/format'

const route = useRoute(); const router = useRouter()
const filters = reactive({ startDate: '', endDate: '', containerId: String(route.query.container_id ?? '') })
const options = ref<ContainerComparisonItem[]>([]); const detail = ref<ContainerDetail | null>(null); const baseline = ref<OverviewData | null>(null); const trend = ref<TrendPoint[]>([]); const loading = ref(true); const error = ref(''); let requestVersion = 0
const selectedOption = computed(() => options.value.find((item) => item.containerId === filters.containerId))
const periodLabel = computed(() => detail.value?.startDate && detail.value?.endDate ? `${detail.value.startDate} 至 ${detail.value.endDate}` : '当前筛选范围暂无销售日期')
const leadGrade = computed(() => [...(detail.value?.grades ?? [])].filter((item) => item.salesQuantity > 0).sort((a, b) => b.salesQuantity - a.salesQuantity)[0])
const sourceFileCount = computed(() => new Set((detail.value?.records ?? []).map((record) => record.sourceFileId).filter(Boolean)).size)
const unknownGradeCount = computed(() => (detail.value?.records ?? []).filter((record) => !record.grade).length)
const baselineRows = computed(() => detail.value?.grades.map((grade) => { const reference = baseline.value?.grades.find((item) => item.grade === grade.grade); const delta = grade.weightedAvgPrice !== null && reference?.weightedAvgPrice != null ? grade.weightedAvgPrice / reference.weightedAvgPrice - 1 : null; return { ...grade, baselinePrice: reference?.weightedAvgPrice ?? null, delta } }) ?? [])
const salesKpis = computed(() => [
  { label: '销售量', value: detail.value ? formatNumber(detail.value.total.salesQuantity) : '—', note: `占全局 ${formatPercent(selectedOption.value?.salesQuantityShare)}` },
  { label: '销售额', value: detail.value ? formatCurrency(detail.value.total.salesAmount) : '—', note: `占全局 ${formatPercent(selectedOption.value?.salesAmountShare)}` },
  { label: '加权均价', value: detail.value ? formatPrice(detail.value.total.weightedAvgPrice) : '—', note: '销售额 ÷ 销售量' },
  { label: '销售额排名', value: selectedOption.value?.rank?.salesAmount ? `第${selectedOption.value.rank.salesAmount}名` : '—', note: `共 ${options.value.length || '—'} 个货柜` },
])
async function loadOptions() { options.value = await getContainerComparison({ startDate: filters.startDate, endDate: filters.endDate }); if (!filters.containerId && options.value.length) filters.containerId = options.value[0].containerId }
async function refresh() { if (filters.startDate && filters.endDate && filters.startDate > filters.endDate) { error.value = '开始日期不能晚于结束日期'; return }; const version = ++requestVersion; loading.value = true; error.value = ''; try { await loadOptions(); if (!filters.containerId) return; const dateFilters = { startDate: filters.startDate, endDate: filters.endDate }; const [nextDetail, nextTrend, nextBaseline] = await Promise.all([getContainerDetail(filters.containerId, dateFilters), getTrend({ ...dateFilters, containerId: filters.containerId }), getOverview(dateFilters)]); if (version !== requestVersion) return; detail.value = nextDetail; trend.value = nextTrend; baseline.value = nextBaseline; router.replace({ query: { ...route.query, container_id: filters.containerId } }) } catch (caught) { if (version === requestVersion) error.value = caught instanceof Error ? caught.message : '单柜数据加载失败' } finally { if (version === requestVersion) loading.value = false } }
onMounted(refresh)
</script>

<template>
  <div class="container-dashboard">
    <header class="dashboard-head"><div><p class="eyebrow">CONTAINER DIAGNOSIS</p><h1>单柜经营诊断</h1><p>以 A / B / C 销售结构为主线，快速定位货柜量价与等级问题。</p></div><div class="head-actions"><RouterLink class="secondary-button" to="/overview">货柜重点对比</RouterLink><div class="period-stamp"><span>销售周期</span><strong>{{ periodLabel }}</strong></div></div></header>
    <div class="dashboard-toolbar"><nav class="view-switch" aria-label="分析视图"><RouterLink to="/overview">全局汇总</RouterLink><RouterLink to="/containers" aria-current="page">单柜诊断</RouterLink></nav><form class="filter-bar" @submit.prevent="refresh"><label>货柜<select v-model="filters.containerId" required @change="refresh"><option value="" disabled>选择货柜</option><option v-for="item in options" :key="item.containerId" :value="item.containerId">{{ item.containerName }}</option></select></label><label>开始日期<input v-model="filters.startDate" type="date" @change="refresh"></label><label>结束日期<input v-model="filters.endDate" type="date" @change="refresh"></label><button class="primary-button" type="submit" :disabled="loading || !filters.containerId">{{ loading ? '分析中' : '刷新' }}</button></form></div>
    <div v-if="error" class="error-banner" role="alert"><span><strong>诊断加载失败</strong>{{ error }}</span><button type="button" @click="refresh">重试</button></div>
    <div v-if="!loading && !options.length" class="empty-state prominent"><strong>暂无可诊断货柜</strong><span>请先导入包含货柜号的销售结算单。</span><RouterLink class="primary-button" to="/imports">前往导入</RouterLink></div>
    <template v-else>
      <section class="container-banner"><div class="container-identity"><span class="status-dot" aria-hidden="true" /><div><span class="eyebrow">CURRENT CONTAINER</span><strong>{{ detail?.containerName ?? selectedOption?.containerName ?? filters.containerId }}</strong><small>{{ filters.containerId }} · {{ periodLabel }}</small></div></div><div class="banner-focus"><span>复盘重点</span><strong>A / B / C 销售结构</strong><small>回款与结算仅作辅助</small></div></section>
      <section class="kpi-grid" aria-label="销售核心指标"><article v-for="item in salesKpis" :key="item.label" class="kpi-card"><span>{{ item.label }}</span><strong>{{ item.value }}</strong><small>{{ item.note }}</small></article></section>
      <section class="dashboard-grid grade-grid"><div class="panel grade-summary-panel"><GradeSummary :grades="detail?.grades ?? []" :total="detail?.total ?? { salesQuantity: 0, salesAmount: 0, weightedAvgPrice: null }" :loading="loading" :title="`${detail?.containerName ?? '当前货柜'} 等级表现`" /></div><div class="panel pie-panel"><GradePieChart :grades="detail?.grades ?? []" :loading="loading" /></div></section>
      <section class="insight-strip" aria-label="诊断摘要"><div><span>主力等级</span><strong>{{ leadGrade ? `${leadGrade.grade} · ${gradeLabel(leadGrade.grade)}` : '暂无数据' }}</strong><small>{{ leadGrade ? `销量占比 ${formatPercent(leadGrade.quantityShare)}` : '等待明细' }}</small></div><div><span>经营异常</span><strong :class="{ alert: detail?.operatingAnomalies.length }">{{ detail?.operatingAnomalies.length ?? 0 }} 条</strong><small>{{ detail?.operatingAnomalies.length ? '需要优先复核' : '当前未发现异常' }}</small></div><div><span>来源文件</span><strong>{{ sourceFileCount || '—' }}</strong><small>{{ detail?.records.length ?? 0 }} 条明细</small></div><div><span>等级待确认</span><strong :class="{ alert: unknownGradeCount }">{{ unknownGradeCount }}</strong><small>{{ unknownGradeCount ? '原始值未映射' : '等级已归一化' }}</small></div></section>
      <section class="dashboard-grid analysis-grid"><div class="panel trend-panel"><TrendChart :points="trend" :loading="loading" title="该柜每日量价变化" /></div><div class="panel baseline-panel"><header class="panel-head"><div><p class="eyebrow">BENCHMARK</p><h2>横向基准与等级价差</h2></div><span>同期整体</span></header><div v-if="loading" class="skeleton-block">正在计算同期基线</div><div v-else class="baseline-list"><div v-for="row in baselineRows" :key="row.grade" class="baseline-row"><span class="grade-badge" :class="`grade-${row.grade.toLowerCase()}`">{{ row.grade }}</span><div><strong>{{ gradeLabel(row.grade) }}</strong><small>本柜 {{ formatPrice(row.weightedAvgPrice) }} · 整体 {{ formatPrice(row.baselinePrice) }}</small></div><span :class="['delta-pill', { negative: row.delta !== null && row.delta < 0 }]">{{ row.delta === null ? '暂无对比' : `${row.delta >= 0 ? '+' : ''}${formatPercent(row.delta)}` }}</span></div></div></div></section>
      <section class="compact-alerts panel"><header class="panel-head"><div><p class="eyebrow">ATTENTION</p><h2>经营异常</h2></div><span>优先复核量、价与等级偏离</span></header><div v-if="!detail?.operatingAnomalies.length" class="empty-inline">当前未发现经营异常</div><ul v-else class="alert-list inline-alerts"><li v-for="(item, index) in detail.operatingAnomalies" :key="index" class="alert-item danger"><span class="alert-code">经营</span><div><strong>{{ item.reason }}</strong><p>当前 {{ formatAnomalyValue(item.type, item.metric) }} · 基线 {{ formatAnomalyValue(item.type, item.baseline) }}</p></div></li></ul></section>
      <details class="secondary-drawer"><summary><span><b>辅助信息与明细追溯</b><small>结算、来源文件、标准化销售记录</small></span><em>展开</em></summary><div class="drawer-grid"><section class="panel"><header class="panel-head"><div><p class="eyebrow">SETTLEMENT CONTEXT</p><h2>回款与结算辅助</h2></div></header><dl class="settlement-strip"><div><dt>售后金额</dt><dd>{{ detail?.settlement.afterSalesAmount == null ? '暂无数据' : formatCurrency(detail.settlement.afterSalesAmount) }}</dd></div><div><dt>费用合计</dt><dd>{{ detail?.settlement.feeAmount == null ? '暂无数据' : formatCurrency(detail.settlement.feeAmount) }}</dd></div><div><dt>清关税费</dt><dd>{{ detail?.settlement.customsTax == null ? '暂无数据' : formatCurrency(detail.settlement.customsTax) }}</dd></div><div><dt>应付结算</dt><dd>{{ detail?.settlement.payableAmount == null ? '暂无数据' : formatCurrency(detail.settlement.payableAmount) }}</dd></div></dl></section><section class="panel"><header class="panel-head"><div><p class="eyebrow">TRACEABILITY</p><h2>标准化销售明细</h2></div><span>{{ detail?.records.length ?? 0 }} 条</span></header><div v-if="!detail?.records.length" class="empty-inline">当前范围没有销售明细</div><div v-else class="table-wrap trace-table"><table><thead><tr><th>日期</th><th>等级</th><th>数量</th><th>金额</th><th>来源</th></tr></thead><tbody><tr v-for="record in detail.records" :key="record.id"><td>{{ record.saleDate }}</td><td>{{ record.grade ? gradeLabel(record.grade) : '未知' }}</td><td>{{ formatNumber(record.quantity) }}</td><td>{{ formatCurrency(record.amount) }}</td><td><a class="text-link" :href="recordSourceUrl(record.id)">#{{ record.sourceFileId ?? '—' }}</a></td></tr></tbody></table></div></section></div></details>
      <details class="secondary-drawer contribution-drawer"><summary><span><b>等级贡献细分</b><small>查看本柜与整体等级贡献关系</small></span><em>展开</em></summary><div class="contribution-body"><ComparisonPanel :global-grades="baseline?.grades ?? []" :global-total="baseline?.total" :selected-grades="detail?.grades" :selected-total="detail?.total" /></div></details>
    </template>
  </div>
</template>

